 1→import { test } from "node:test";
 2→import assert from "node:assert/strict";
 3→import { planVisibility, renderPlan, HIDDEN } from "./plan-visibility.mjs";
 4→
 5→const WRONG = "skl-sZFb3KatWY6m", RIGHT = "skl-oBaDO5CceKnr", PEND = "skl-pending";
 6→
 7→const baseline = {
 8→  assets: {
 9→    [WRONG]: { baseline_visibility: "team" },
10→    [RIGHT]: { baseline_visibility: "team" },
11→    [PEND]: { baseline_visibility: "team" },
12→  },
13→  decisions: [
14→    { asset_id: WRONG, decision: "reject", reasons: ["rule reject: a corrected record exists (reason=wrong)"] },
15→    { asset_id: RIGHT, decision: "admit", reasons: ["rule admit"] },
16→    { asset_id: PEND, decision: "pending", reasons: ["cold start"] },
17→  ],
18→};
19→
20→test("apply from the baseline: only the rejected asset changes, to private", () => {
21→  const plan = planVisibility({ mode: "apply", baseline, current: { [WRONG]: "team", [RIGHT]: "team", [PEND]: "team" } });
22→  assert.deepEqual(plan.changes.map((c) => [c.asset_id, c.from, c.to]), [[WRONG, "team", HIDDEN]]);
23→  assert.match(plan.changes[0].because, /reject → private/);
24→  assert.equal(plan.unchanged.length, 2);
25→  assert.ok(plan.unchanged.find((u) => u.asset_id === PEND).because.includes("does not hide what it could not judge"));
26→  assert.deepEqual(plan.unreadable, []);
27→});
28→
29→test("apply is idempotent: already-private rejected asset is unchanged", () => {
30→  const plan = planVisibility({ mode: "apply", baseline, current: { [WRONG]: HIDDEN, [RIGHT]: "team", [PEND]: "team" } });
31→  assert.deepEqual(plan.changes, []);
32→});
33→
34→test("reset restores the baseline regardless of decisions", () => {
35→  const plan = planVisibility({ mode: "reset", baseline, current: { [WRONG]: HIDDEN, [RIGHT]: HIDDEN, [PEND]: "team" } });
36→  const byId = (a, b) => a[0].localeCompare(b[0]);
37→  assert.deepEqual(plan.changes.map((c) => [c.asset_id, c.to]).sort(byId), [[WRONG, "team"], [RIGHT, "team"]].sort(byId));
38→  assert.ok(plan.changes.every((c) => /reset to baseline/.test(c.because)));
39→});
