624→export function createSkillBridgeHandler(
625→  config: ProxyConfig,
626→  deps: SkillBridgeDeps = {},
627→): (c: Context) => Promise<Response> {
628→  const fetcher = deps.fetcher ?? globalThis.fetch.bind(globalThis);
629→
630→  return async (c: Context): Promise<Response> => {
631→    const t0 = (deps.now ?? Date.now)();
632→
633→    const path = new URL(c.req.url).pathname;
634→    const sub = extractSubpath(path);
635→    // 前置校验早退埋点: 每个 return 前都发一条 reject_reason 非空的 bridge_call。
636→    // sessionKey 此刻可能还没派生, 允许传 "" (helper 兜底 agentSource='unknown')。
637→    if (!sub) {
638→      emitBridgeRejectTelemetry({
639→        sessionKey: "", bridgeSource: "skill-bridge",
640→        rejectReason: "unknown_path", httpStatus: 404,
641→      });
642→      return envelope(40401, `${TAG} unknown path ${path}`, 404);
643→    }
644→    if (!ALLOWED_SUBPATHS.has(sub)) {
645→      emitBridgeRejectTelemetry({
646→        sessionKey: "", bridgeSource: "skill-bridge",
647→        rejectReason: "subpath_forbidden", httpStatus: 403,
648→        executedEndpoint: sub,
649→      });
650→      return envelope(40301, `${TAG} subpath '${sub}' not allowed via bridge`, 403);
651→    }
652→    if (c.req.method !== "POST") {
653→      emitBridgeRejectTelemetry({
654→        sessionKey: "", bridgeSource: "skill-bridge",
655→        rejectReason: "method_not_allowed", httpStatus: 405,
656→        executedEndpoint: sub,
657→      });
658→      return envelope(40501, `${TAG} method ${c.req.method} not allowed`, 405);
659→    }
660→
661→    const ct = c.req.header("content-type") ?? "";
662→    if (!ct.toLowerCase().includes("application/json")) {
663→      emitBridgeRejectTelemetry({
664→        sessionKey: "", bridgeSource: "skill-bridge",
665→        rejectReason: "content_type_invalid", httpStatus: 415,
666→        executedEndpoint: sub,
667→      });
668→      return envelope(41501, `${TAG} content-type must be application/json`, 415);
669→    }
670→
671→    // Session must be initialized — IdFields come from there.
672→    // curl 模板只带 (x-conversation-id, x-tdai-service-id) 两个 header;
673→    // L1 miss 时用它俩去 nottl/<spaceId>/<sessionId>/binding.json 反查。
674→    const sessionKey = deriveSessionId(c);
675→    if (!sessionKey) {
676→      emitBridgeRejectTelemetry({
677→        sessionKey: "", bridgeSource: "skill-bridge",
678→        rejectReason: "missing_conversation_id", httpStatus: 401,
679→        executedEndpoint: sub,
680→      });
681→      return envelope(40101, `${TAG} missing x-conversation-id (or x-session-id / x-chat-id / x-thread-id) header`, 401);
682→    }
683→    const spaceId = c.req.header("x-tdai-service-id")
684→      ?? config.tdai?.serviceId
685→      ?? config.coreSkill?.serviceId
686→      ?? "";
687→
688→    // Backing storage for extract trigger + version pin.
689→    // When storage.enabled + mode!=off → ProxyStorage (Kv* repos).
690→    // Otherwise → Redis (or null when disabled).
691→    const backing = resolveBacking(config);
692→    const pinRepoInline = backing.pinRepo;
693→    const bindingRepoInline = backing.bindingRepo;
694→
695→    let ids = loadSessionIdsL1(sessionKey);
696→    if (!ids && bindingRepoInline && spaceId) {
697→      console.log(`${TAG} session=${sessionKey} L1 miss → L2 binding lookup (space=${spaceId})`);
698→      ids = await loadSessionIdsL2(bindingRepoInline, spaceId, sessionKey);
699→    }
700→    if (!ids) {
701→      emitBridgeRejectTelemetry({
702→        sessionKey, bridgeSource: "skill-bridge",
703→        rejectReason: "session_not_initialized", httpStatus: 401,
704→        executedEndpoint: sub, spaceId,
705→      });
706→      return envelope(40101, `${TAG} session not initialized; cannot derive identity`, 401);
707→    }
708→    // backing.redis 之前给老链路 SkillExtractTrigger 用, 老链路已删,
709→    // 本函数体内不再直接使用 redis; backing 结构上保留是因为 pinRepo
710→    // 走 redis 的分支还需要它。
711→
712→    // 消融实验：allowLlmWrite=false 时拒绝写操作
713→    const allowLlmWrite = config.skillRuntime?.allowLlmWrite ?? false;
714→    if (!allowLlmWrite && WRITE_SUBPATHS.has(sub)) {
715→      emitBridgeRejectTelemetry({
716→        sessionKey, bridgeSource: "skill-bridge",
